const getUnconfirmedAfterReminder = `-- name: GetUnconfirmedAfterReminder :many
SELECT id, complex_id, court_id, client_id, date, start_time, duration_minutes, price, deposit_amount, status, reminder_sent_2h, notes, created_by, created_at, updated_at, refund_intent_at, span, collection_status, refund_status, client_first_name, client_last_name, client_phone, client_email, hold_token_hash, hold_ip, series_id, attended_at, hold_started_at FROM bookings WHERE false
`

// Kept for backwards compatibility with generated code. No longer used by business logic.
func (q *Queries) GetUnconfirmedAfterReminder(ctx context.Context) ([]Booking, error) {
	rows, err := q.db.Query(ctx, getUnconfirmedAfterReminder)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Booking
	for rows.Next() {
		var i Booking
		if err := rows.Scan(
			&i.ID,
			&i.ComplexID,
			&i.CourtID,
			&i.ClientID,
			&i.Date,
			&i.StartTime,
			&i.DurationMinutes,
			&i.Price,
			&i.DepositAmount,
			&i.Status,
			&i.ReminderSent2h,
			&i.Notes,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RefundIntentAt,
			&i.Span,
			&i.CollectionStatus,
			&i.RefundStatus,
			&i.ClientFirstName,
			&i.ClientLastName,
			&i.ClientPhone,
			&i.ClientEmail,
			&i.HoldTokenHash,
			&i.HoldIp,
			&i.SeriesID,
			&i.AttendedAt,
			&i.HoldStartedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

